(1110740, 136300, 23458, '<td valign="top">Stunning. Love the reflections and colours, one of the btter spider web shots I''ve seen. DOF is perfect. 10.</td>', 'Stunning. Love the reflections and colours, one of the btter spider web shots I''ve seen. DOF is perfect. 10.', '2005-01-16 07:24:35.000000', NULL, 1),
(1110741, 135240, 20608, '<td valign="top">Its a bit dark but I love the mood of it.</td>', 'Its a bit dark but I love the mood of it.', '2005-01-16 07:24:58.000000', NULL, 1),
