(1110924, 132538, 29477, '<td valign="top">Simple and effective.  Very tranquil...good shot.</td>', 'Simple and effective.  Very tranquil...good shot.', '2005-01-16 08:54:23.000000', NULL, 1),
(1110925, 133252, 16739, '<td valign="top">nice shot , looks over processed</td>', 'nice shot , looks over processed', '2005-01-16 08:54:39.000000', NULL, 1),
