(1111595, 132456, 24128, '<td valign="top">great mood, really nice still life - well done</td>', 'great mood, really nice still life - well done', '2005-01-16 13:20:40.000000', NULL, 1),
(1111596, 136329, 16241, '<td valign="top">i saved the other one as a fav long ago! :)  cool foto</td>', 'i saved the other one as a fav long ago! :)  cool foto', '2005-01-16 13:20:58.000000', NULL, 1),
(1111597, 136049, 31511, '<td valign="top">Gorgeous land! Didn''t Ansel Adams do some work here?</td>', 'Gorgeous land! Didn''t Ansel Adams do some work here?', '2005-01-16 13:21:22.000000', NULL, 1),
(1111599, 135919, 8643, '<td valign="top">Beautiful action shot, captures the moment, the movement , the skill, - great!</td>', 'Beautiful action shot, captures the moment, the movement , the skill, - great!', '2005-01-16 13:23:16.000000', NULL, 1),
(1111600, 134345, 26475, '<td valign="top">Wow. A tremendous shot! Need a little more from the gray scale, but wonderfully done. 8</td>', 'Wow. A tremendous shot! Need a little more from the gray scale, but wonderfully done. 8', '2005-01-16 13:23:19.000000', NULL, 1),
(1111601, 135893, 24128, '<td valign="top">very interesting, it seems from the image that you needed to take a sideways step to the left though</td>', 'very interesting, it seems from the image that you needed to take a sideways step to the left though', '2005-01-16 13:23:54.000000', NULL, 1),
(1111604, 134410, 8643, '<td valign="top">Beautiful action shot!</td>', 'Beautiful action shot!', '2005-01-16 13:25:06.000000', NULL, 1),
(1111605, 134214, 3032, '<td valign="top">Good capture, funny to see how the guy is checking her out via the mirror. :)<br/> <br/></td>', 'Good capture, funny to see how the guy is checking her out via the mirror. :) ', '2005-01-16 13:25:08.000000', NULL, 1),
