(1121730, 136000, 15002, '<td valign="top">Beautiful scene.  A ND filter would allow for a slower shutter speed, and give the water a softer look.</td>', 'Beautiful scene.  A ND filter would allow for a slower shutter speed, and give the water a softer look.', '2005-01-20 16:00:33.000000', NULL, 1),
(1121732, 136414, 15002, '<td valign="top">Absolutely georgous!  The sky is incredible, and the "line out" of the sand bar is very well done</td>', 'Absolutely georgous!  The sky is incredible, and the "line out" of the sand bar is very well done', '2005-01-20 16:02:29.000000', NULL, 1),
(1121737, 136821, 15002, '<td valign="top">Excellent reflection.  Tall foreground adds nice depth.  Alittle crowded on the left IMO, but overall very nicely done.</td>', 'Excellent reflection.  Tall foreground adds nice depth.  Alittle crowded on the left IMO, but overall very nicely done.', '2005-01-20 16:04:35.000000', NULL, 1),
(1121738, 132909, 4008, '<td valign="top">very nice intimate portrait, a pity you did not put more distance between them and the wall. The structure in the wall is highly distracting in my opinion and should have been put out of focus.</td>', 'very nice intimate portrait, a pity you did not put more distance between them and the wall. The structure in the wall is highly distracting in my opinion and should have been put out of focus.', '2005-01-20 16:05:47.000000', NULL, 1),
(1121743, 136757, 4008, '<td valign="top">great action shot, great panning, the car at the back adds an extra dimension.</td>', 'great action shot, great panning, the car at the back adds an extra dimension.', '2005-01-20 16:08:05.000000', NULL, 1),
(1121744, 136229, 15002, '<td valign="top">Beautiful subject and exposure.  If I had to nit pik- IMO she is too centered, and her hair looks too "arranged".</td>', 'Beautiful subject and exposure.  If I had to nit pik- IMO she is too centered, and her hair looks too "arranged".', '2005-01-20 16:08:33.000000', NULL, 1),
