(1123474, 134562, 11897, '<td valign="top">Nice shot but a little distant.</td>', 'Nice shot but a little distant.', '2005-01-21 13:29:15.000000', NULL, 1),
(1123476, 133758, 14671, '<td valign="top">Interesting but the lack of color is very disturbing.  Perhaps a selective desaturation would have been the better choice.  Because of the high contrast it also look a little blurry.  Good luck and keep up the good work in 2005.</td>', 'Interesting but the lack of color is very disturbing.  Perhaps a selective desaturation would have been the better choice.  Because of the high contrast it also look a little blurry.  Good luck and keep up the good work in 2005.', '2005-01-21 13:30:44.000000', NULL, 1),
