(1124513, 133041, 31434, '<td valign="top">Very nice...</td>', 'Very nice...', '2005-01-21 22:55:50.000000', NULL, 1),
(1124527, 133785, 8624, '<td valign="top">awesome composition. The framing of the girl and guitar is really visually appealing. I love how her hair masks her face. I don''t care for the yellow border at all - it detracts from an otherwise excellent image, but I don''t mind it enough to really penalize you for it - 9 from me!</td>', 'awesome composition. The framing of the girl and guitar is really visually appealing. I love how her hair masks her face. I don''t care for the yellow border at all - it detracts from an otherwise excellent image, but I don''t mind it enough to really penalize you for it - 9 from me!', '2005-01-21 23:08:44.000000', NULL, 1),
(1124532, 136525, 31434, '<td valign="top">Great Photo....nice caption</td>', 'Great Photo....nice caption', '2005-01-21 23:14:34.000000', NULL, 1),
(1124555, 132255, 16046, '<td valign="top">What an excellent shot perfect 10</td>', 'What an excellent shot perfect 10', '2005-01-21 23:33:27.000000', NULL, 1),
(1124594, 135345, 16046, '<td valign="top">Excellent macro, nice details, love the wings and back of head. 10</td>', 'Excellent macro, nice details, love the wings and back of head. 10', '2005-01-22 00:24:13.000000', NULL, 1),
(1124596, 135565, 16046, '<td valign="top">This photo is great, the transition from red to blue is aweome, really fine art, 10</td>', 'This photo is great, the transition from red to blue is aweome, really fine art, 10', '2005-01-22 00:27:10.000000', NULL, 1),
(1124597, 135427, 16046, '<td valign="top">Nice girl, very soft touch here, excellent</td>', 'Nice girl, very soft touch here, excellent', '2005-01-22 00:28:15.000000', NULL, 1),
(1124598, 136246, 16046, '<td valign="top">Nice, but too dead center for me, I would prefer the tower more to the right. good exposure.</td>', 'Nice, but too dead center for me, I would prefer the tower more to the right. good exposure.', '2005-01-22 00:30:51.000000', NULL, 1),
(1124600, 136706, 16046, '<td valign="top">That''s cool, great in B/W, thanks for sharing.</td>', 'That''s cool, great in B/W, thanks for sharing.', '2005-01-22 00:33:36.000000', NULL, 1),
(1124602, 135135, 16046, '<td valign="top">This rocks! great shadow and light</td>', 'This rocks! great shadow and light', '2005-01-22 00:35:48.000000', NULL, 1),
