(1125167, 135345, 25388, '<td valign="top">remarkable detail and color</td>', 'remarkable detail and color', '2005-01-22 11:55:25.000000', NULL, 1),
(1125191, 136381, 17033, '<td valign="top">The way this loaded, I just the saw the face  and the window: all seemed to fit with the title. A thoughtful kind of picture. So I don''t understand what purpose the nudity has here..what it adds to the mood.</td>', 'The way this loaded, I just the saw the face  and the window: all seemed to fit with the title. A thoughtful kind of picture. So I don''t understand what purpose the nudity has here..what it adds to the mood.', '2005-01-22 12:18:07.000000', NULL, 1),
(1125192, 136832, 6870, '<td valign="top">Super composition and the grain is used marvelously here. B/W a great choice, too. A photo to be proud of, that''s for sure. 9</td>', 'Super composition and the grain is used marvelously here. B/W a great choice, too. A photo to be proud of, that''s for sure. 9', '2005-01-22 12:18:11.000000', NULL, 1),
