(1129822, 136688, 29404, '<td valign="top">very well done</td>', 'very well done', '2005-01-24 20:21:39.000000', NULL, 1),
(1129823, 135296, 29404, '<td valign="top">nice shot ...very moving capture</td>', 'nice shot ...very moving capture', '2005-01-24 20:22:25.000000', NULL, 1),
(1129824, 132149, 19936, '<td valign="top">Great shot.  Love the clarity and the interest factor of the characters.  Suffers some from what looks like over NI and distracting background on teh top of photo (maybe a closer crop?).</td>', 'Great shot.  Love the clarity and the interest factor of the characters.  Suffers some from what looks like over NI and distracting background on teh top of photo (maybe a closer crop?).', '2005-01-24 20:24:06.000000', NULL, 1),
