INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1130071, 132991, 23394, '<td valign="top">oh yeah, you got your photoshop down!  most excellent work, popping out the image here.  i really, really hope this does well for you, because i know how hard you worked to make this image happen.  and, in all honesty, i don''t think any score here will ever do this image justice.  i just hope you have it printed large, and hanging somewhere prominent, giving it the attention it deserves.  great work, all the way around!</td>', 'oh yeah, you got your photoshop down!  most excellent work, popping out the image here.  i really, really hope this does well for you, because i know how hard you worked to make this image happen.  and, in all honesty, i don''t think any score here will ever do this image justice.  i just hope you have it printed large, and hanging somewhere prominent, giving it the attention it deserves.  great work, all the way around!', '2005-01-24 22:44:16.000000', NULL, 1),
(1130072, 132622, 31307, '<td valign="top">Whoa.  Neat use of saturation.  I really like the surreal feel of it.  Great job!</td>', 'Whoa.  Neat use of saturation.  I really like the surreal feel of it.  Great job!', '2005-01-24 22:44:20.000000', NULL, 1),
(1130077, 132698, 23394, '<td valign="top">how absolutely fun!  not to minimize any commenting efforts of others, i do hope you disregard any attempts suggested to improve this image, because there''s not a single thing that would make it better!  great work, all the way around.  what a treat.  thanks for sharing.  good luck with this, and the challenges yet to come!</td>', 'how absolutely fun!  not to minimize any commenting efforts of others, i do hope you disregard any attempts suggested to improve this image, because there''s not a single thing that would make it better!  great work, all the way around.  what a treat.  thanks for sharing.  good luck with this, and the challenges yet to come!', '2005-01-24 22:46:33.000000', NULL, 1),
