(1134038, 134359, 24079, '<td valign="top">Oh I love the soft effect! Good job.</td>', 'Oh I love the soft effect! Good job.', '2005-01-26 19:08:20.000000', NULL, 1),
(1134039, 132158, 19708, '<td valign="top">Great composition and subject matter. Lighting and detail are good, rich in color without being over-saturated. Tone sets a nice mood with the blue reflection. ((8))</td>', 'Great composition and subject matter. Lighting and detail are good, rich in color without being over-saturated. Tone sets a nice mood with the blue reflection. ((8))', '2005-01-26 19:08:59.000000', NULL, 1),
