(1137387, 133528, 10522, '<td valign="top">PURE QUALITY, EXCELLENT, SUPERB, NEED I SAY MORE.</td>', 'PURE QUALITY, EXCELLENT, SUPERB, NEED I SAY MORE.', '2005-01-28 16:14:05.000000', NULL, 1),
(1137413, 134322, 23471, '<td valign="top">I dont really like the lack of symmetry in this photo.  I think that by cropping out the space after the last pillar to the left, you will not only make the background symmetrical but also bring the umbrella into the direct center of the shot.</td>', 'I dont really like the lack of symmetry in this photo.  I think that by cropping out the space after the last pillar to the left, you will not only make the background symmetrical but also bring the umbrella into the direct center of the shot.', '2005-01-28 16:31:56.000000', NULL, 1),
(1137416, 136816, 23471, '<td valign="top">really like the tones you used for this shot.</td>', 'really like the tones you used for this shot.', '2005-01-28 16:35:31.000000', NULL, 1),
